using ContosoUniversity.Models;
using ContosoUniversity.Services;
using FluentAssertions;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain existing queue items from other tests (static queue)
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotificationWithCorrectMessage()
        {
            // Arrange & Act
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            notification.Should().NotBeNull();
            notification!.EntityType.Should().Be("Student");
            notification.EntityId.Should().Be("1");
            notification.Operation.Should().Be("CREATE");
            notification.Message.Should().Be("New Student 'John Doe' has been created");
            notification.CreatedBy.Should().Be("Admin");
            notification.IsRead.Should().BeFalse();
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            // Arrange & Act
            _service.SendNotification("Course", "42", EntityOperation.UPDATE, "Teacher");

            // Assert
            var notification = _service.ReceiveNotification();
            notification.Should().NotBeNull();
            notification!.Message.Should().Be("Course (ID: 42) has been updated");
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
        {
            // Arrange & Act
            _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE);

            // Assert
            var notification = _service.ReceiveNotification();
            notification.Should().NotBeNull();
            notification!.Message.Should().Be("Department 'Engineering' has been deleted");
            notification.CreatedBy.Should().Be("System");
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            // Arrange & Act
            _service.SendNotification("Student", "1", EntityOperation.CREATE, null);

            // Assert
            var notification = _service.ReceiveNotification();
            notification.Should().NotBeNull();
            notification!.CreatedBy.Should().Be("System");
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Act
            var notification = _service.ReceiveNotification();

            // Assert
            notification.Should().BeNull();
        }

        [Fact]
        public void ReceiveNotification_MultipleMessages_ReturnsInFifoOrder()
        {
            // Arrange
            _service.SendNotification("Student", "1", "First", EntityOperation.CREATE);
            _service.SendNotification("Student", "2", "Second", EntityOperation.CREATE);

            // Act & Assert
            var first = _service.ReceiveNotification();
            first!.Message.Should().Contain("First");

            var second = _service.ReceiveNotification();
            second!.Message.Should().Contain("Second");

            _service.ReceiveNotification().Should().BeNull();
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act - MarkAsRead is a no-op for in-memory, should not throw
            var act = () => _service.MarkAsRead(999);
            act.Should().NotThrow();
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            // Arrange
            var before = DateTime.Now;

            // Act
            _service.SendNotification("Student", "1", EntityOperation.CREATE);

            // Assert
            var notification = _service.ReceiveNotification();
            notification!.CreatedAt.Should().BeOnOrAfter(before);
            notification.CreatedAt.Should().BeOnOrBefore(DateTime.Now);
        }
    }
}

