using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using FluentAssertions;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            SeedStudents();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private void SeedStudents()
        {
            _context.Students.AddRange(
                new Student { ID = 1, FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2010-09-01") },
                new Student { ID = 2, FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2012-09-01") },
                new Student { ID = 3, FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2013-09-01") }
            );
            _context.SaveChanges();
        }

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
        {
            // Act
            var result = _controller.Index(null, null, null, null) as ViewResult;

            // Assert
            result.Should().NotBeNull();
            var model = result!.Model as PaginatedList<Student>;
            model.Should().NotBeNull();
            model!.Should().HaveCountGreaterThan(0);
            model[0].LastName.Should().Be("Alexander");
        }

        [Fact]
        public void Index_NameDescSort_ReturnsSortedDescending()
        {
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;
            var model = result!.Model as PaginatedList<Student>;

            model![0].LastName.Should().Be("Anand");
        }

        [Fact]
        public void Index_DateSort_ReturnsSortedByDateAscending()
        {
            var result = _controller.Index("Date", null, null, null) as ViewResult;
            var model = result!.Model as PaginatedList<Student>;

            model![0].EnrollmentDate.Should().Be(DateTime.Parse("2010-09-01"));
        }

        [Fact]
        public void Index_DateDescSort_ReturnsSortedByDateDescending()
        {
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;
            var model = result!.Model as PaginatedList<Student>;

            model![0].EnrollmentDate.Should().Be(DateTime.Parse("2013-09-01"));
        }

        [Fact]
        public void Index_SearchString_FiltersResults()
        {
            var result = _controller.Index(null, null, "Carson", null) as ViewResult;
            var model = result!.Model as PaginatedList<Student>;

            model!.Should().HaveCount(1);
            model[0].FirstMidName.Should().Be("Carson");
        }

        [Fact]
        public void Index_SearchStringNoMatch_ReturnsEmpty()
        {
            var result = _controller.Index(null, null, "NonExistent", null) as ViewResult;
            var model = result!.Model as PaginatedList<Student>;

            model!.Should().HaveCount(0);
        }

        [Fact]
        public void Index_SearchStringResetsPage()
        {
            // When searchString is provided (not null), page should reset to 1
            var result = _controller.Index(null, null, "A", 3) as ViewResult;
            var model = result!.Model as PaginatedList<Student>;

            model!.PageIndex.Should().Be(1);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            result.Should().BeOfType<StatusCodeResult>();
            (result as StatusCodeResult)!.StatusCode.Should().Be(400);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            // Need to add enrollment data for Include to work
            var result = _controller.Details(1);

            result.Should().BeOfType<ViewResult>();
            var student = (result as ViewResult)!.Model as Student;
            student!.FirstMidName.Should().Be("Carson");
            student.LastName.Should().Be("Alexander");
        }

        [Fact]
        public void Create_Get_ReturnsViewWithDefaultDate()
        {
            var result = _controller.Create() as ViewResult;

            result.Should().NotBeNull();
            var student = result!.Model as Student;
            student!.EnrollmentDate.Date.Should().Be(DateTime.Today);
        }

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                FirstMidName = "New",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2023-01-15")
            };

            var result = _controller.Create(student);

            result.Should().BeOfType<RedirectToActionResult>();
            (result as RedirectToActionResult)!.ActionName.Should().Be("Index");
        }

        [Fact]
        public void Create_Post_ValidStudent_SavesInDatabase()
        {
            var student = new Student
            {
                FirstMidName = "New",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2023-01-15")
            };

            _controller.Create(student);

            _context.Students.Should().Contain(s => s.LastName == "Student" && s.FirstMidName == "New");
        }

        [Fact]
        public void Create_Post_MinDateEnrollment_ReturnsViewWithError()
        {
            var student = new Student
            {
                FirstMidName = "Bad",
                LastName = "Date",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student);

            result.Should().BeOfType<ViewResult>();
            _controller.ModelState.IsValid.Should().BeFalse();
            _controller.ModelState["EnrollmentDate"]!.Errors.Should().NotBeEmpty();
        }

        [Fact]
        public void Create_Post_DateBefore1753_ReturnsViewWithError()
        {
            var student = new Student
            {
                FirstMidName = "Old",
                LastName = "Person",
                EnrollmentDate = new DateTime(1700, 1, 1)
            };

            var result = _controller.Create(student);

            result.Should().BeOfType<ViewResult>();
            _controller.ModelState["EnrollmentDate"]!.Errors
                .Should().Contain(e => e.ErrorMessage.Contains("1753"));
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);
            result.Should().BeOfType<StatusCodeResult>();
            (result as StatusCodeResult)!.StatusCode.Should().Be(400);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            var result = _controller.Edit(1) as ViewResult;

            result.Should().NotBeNull();
            var student = result!.Model as Student;
            student!.ID.Should().Be(1);
            student.FirstMidName.Should().Be("Carson");
        }

        [Fact]
        public void Edit_Get_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Edit(999);
            result.Should().BeOfType<NotFoundResult>();
        }

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                ID = 1,
                FirstMidName = "Carson",
                LastName = "Updated",
