        public void Initialize_EmptyDatabase_SeedsStudents()
        {
            DbInitializer.Initialize(_context);

            _context.Students.Should().HaveCount(8);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsInstructors()
        {
            DbInitializer.Initialize(_context);

            _context.Instructors.Should().HaveCount(5);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsDepartments()
        {
            DbInitializer.Initialize(_context);

            _context.Departments.Should().HaveCount(4);
            _context.Departments.Should().Contain(d => d.Name == "English");
            _context.Departments.Should().Contain(d => d.Name == "Mathematics");
            _context.Departments.Should().Contain(d => d.Name == "Engineering");
            _context.Departments.Should().Contain(d => d.Name == "Economics");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourses()
        {
            DbInitializer.Initialize(_context);

            _context.Courses.Should().HaveCount(7);
            _context.Courses.Should().Contain(c => c.Title == "Chemistry");
            _context.Courses.Should().Contain(c => c.Title == "Calculus");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsEnrollments()
        {
            DbInitializer.Initialize(_context);

            _context.Enrollments.Should().HaveCount(11);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
        {
            DbInitializer.Initialize(_context);

            _context.OfficeAssignments.Should().HaveCount(3);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourseAssignments()
        {
            DbInitializer.Initialize(_context);

            _context.CourseAssignments.Should().HaveCount(8);
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            // Seed once
            DbInitializer.Initialize(_context);
            var studentCount = _context.Students.Count();

            // Seed again
            DbInitializer.Initialize(_context);

            _context.Students.Should().HaveCount(studentCount);
        }

        [Fact]
        public void Initialize_SetsCorrectStudentData()
        {
            DbInitializer.Initialize(_context);

            var carson = _context.Students.Single(s => s.LastName == "Alexander");
            carson.FirstMidName.Should().Be("Carson");
            carson.EnrollmentDate.Should().Be(DateTime.Parse("2010-09-01"));
        }

        [Fact]
        public void Initialize_SetsCorrectInstructorData()
        {
            DbInitializer.Initialize(_context);

            var kim = _context.Instructors.Single(i => i.LastName == "Abercrombie");
            kim.FirstMidName.Should().Be("Kim");
            kim.HireDate.Should().Be(DateTime.Parse("1995-03-11"));
        }

        [Fact]
        public void Initialize_DepartmentsHaveAdministrators()
        {
            DbInitializer.Initialize(_context);

            var english = _context.Departments.Single(d => d.Name == "English");
            english.InstructorID.Should().NotBeNull();
        }

        [Fact]
        public void Initialize_EnrollmentsHaveGrades()
        {
            DbInitializer.Initialize(_context);

            // First enrollment for Alexander in Chemistry has Grade A
            var enrollment = _context.Enrollments
                .Where(e => e.Grade == Grade.A)
                .ToList();
            enrollment.Should().NotBeEmpty();
        }
    }
}

